// Carbon installations also contain version-5 legacy TPKs. Select by
// on-disk version, rather than interpreting their records as v8.
private uint ReadTextureVersion(long end)
{
    while (Stream.Position < end)
    {
        if (end - Stream.Position < 8) throw new InvalidDataException("TPK header truncated");
        uint kind = Reader.ReadUInt32(), bytes = Reader.ReadUInt32();
        long stop = checked(Stream.Position + bytes);
        if (stop > end) throw new InvalidDataException("TPK header range");
        if (kind == 0x33310001)
        {
            if (bytes < 4) throw new InvalidDataException("TPK version truncated");
            return Reader.ReadUInt32();
        }
        if ((kind & 0x80000000) != 0)
        {
            uint found = ReadTextureVersion(stop);
            if (found != 0) return found;
        }
        Stream.Position = stop;
    }
    return 0;
}


